mapper.select:
select o.id, o.order_no as orderNo, o.order_name as orderName, u.nick_name as investorName, CASE a.footplate WHEN 0 THEN '币安' WHEN 1 THEN '波场' ELSE '未知' END as exchangeName, o.symbol, o.annualized_rate as annualizedRate, o.income, o.status, o.create_time as createTime, DATEDIFF(NOW(), o.create_time) as runDays from w_order_info o left join w_user_info u on u.user_id = o.user_id left join w_apikey_info a on a.id = o.apikey_id where o.user_id = #{userId}
and a.footplate = #{exchange}
order by o.create_time desc
